#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)

void mainImage(out vec4 O, vec2 C) {
    O = vec4(0);
    vec3 r = iResolution;
    vec3 p; 
    float e = 0.01,s,g = 0.;
    float tm = iTime;
    float hk = 1. + sin(tm * 0.4) * 0.16;  // 1.3
    float jk = 1. + sin(tm * 0.3) * 0.3;  // 0.7
    float ck = 2. + sin(tm * 0.5) * 0.7;  // 2.
    float nk = 1. + sin(tm * 0.6) * 0.3;  // 0.5

    vec3 dir = vec3(1,2,5);

    float offset = r.x * 0.25; // stereo
    float parallax = 1.1;
    if(C.x > r.x * 0.5) {
        offset = -offset;
        parallax = -parallax;
    }

    dir.y = parallax;
    dir.x += cos(iTime);
    dir.z += sin(iTime);
    vec2 Cs = C + vec2(offset,0.);

    for(float i=0.;i<99.;++i) {
        if(e <.001)
            O.xyz += mix(r/r, cos(vec3(7,4,2)+log(s)*.5)*.5+.5, .7)*.6 / i;

        p = vec3(g*(Cs-.5*r.xy)/r.y,g-4.) * 2.;
        p = R(p,normalize(dir),.2);

        p = (2. + sin(fract(iTime * 0.1))) - abs(p);
        p = 2. - abs(p);

        p.x<p.z?p=p.zyx:p;
        p.y<p.z?p=p.xzy:p;
        p.x<p.y?p=p.yxz:p;

        s=2.;
        for(int j=0;j++<6;) {
            p=hk-abs(p-jk);
            e=dot(p,p);
            s*=e=3./min(e,ck)+2./min(e,nk);
            p=abs(p)*e-vec3(2,7,1);
        }

        g+=e=length(p.yz)/s;
    }

    O = pow(O,vec4(1.5,2.2,2.8,1));    
    if(abs(C.x - r.x * 0.5) < 0.8) O = vec4(1.);
}
